-- Scope company/person/funding profile discovery to the actual entity and outputs.
-- 47,258 + ceil(15%) = 54,347 micro-USDC; EUR conversion rounds up to exactly 0.05
-- at the configured 0.92 display rate, including the micro-unit quote ceiling.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('apiosk-crunchbase'));
UPDATE catalog.capabilities SET name='Fetch company profile, founders, employees, board members, funding rounds and investors',description='Fetch company profile, founders, employees, board members, funding rounds and investors. Retrieve one identified organization, its description, website, headquarters, headcount, founders, employee profiles, board members and advisors, funding rounds, raised amounts and investors. Returns the available public relationship cards in one company-profile call; no separate people or funding search is needed for those cards.' WHERE slug='company.crunchbase-profile';
UPDATE catalog.capabilities SET name='Fetch official professional profile and company relationships',description='Fetch official professional profile and company relationships. Retrieve one identified professional person, biography, current jobs, board roles, founded organizations and investments. Requires a person profile identifier, not a company identifier.' WHERE slug='person.crunchbase-profile';
UPDATE catalog.capabilities SET name='Fetch official funding round, amount and investor relationships',description='Fetch official funding round, amount and investor relationships. Retrieve one identified funding round, announcement date, investment stage, money raised, funded company and lead investors. Requires a funding-round identifier, not a company identifier.' WHERE slug='funding.crunchbase-profile';
UPDATE providers.api_endpoints e SET price=0.047258 FROM providers.apis a WHERE a.id=e.api_id AND a.slug='apimarket-magicapi-crunchbase-bbcca0a6' AND e.method='POST' AND e.origin_override='https://mcp.crunchbase.com' AND e.path IN ('/mcp/cb_entity_autocomplete','/mcp/cb_search_query','/mcp/cb_entity_get','/mcp/cb_reference');
UPDATE providers.apis SET listing_metadata=jsonb_set(listing_metadata,'{official_mcp,pricing}','{"listAtomic":47258,"buyerAtomic":54347,"buyerMarkupBps":1500,"displayCurrency":"EUR","displayAmount":0.05,"displayRate":0.92,"rateAsOf":"2026-08-21","approvedOn":"2026-10-11","unit":"tools/call","internalEnrichmentIncluded":true}'::jsonb) WHERE slug='apimarket-magicapi-crunchbase-bbcca0a6';
COMMIT;
